package startup

import (
	"strings"
	"testing"

	tea "charm.land/bubbletea/v2"

	"crude/tui/cell"
	"crude/tui/ui"
	"crude/types"
)

func TestNavigationOnlyStartupUsesBanner(t *testing.T) {
	for _, kind := range []string{"home", "root", "personal", "", "documents"} {
		t.Run(kind, func(t *testing.T) {
			m := fixture(t, &fakeStartup{}, false)
			m.root.initial.FolderKind = kind
			text := paintText(m)
			// An independent artwork fragment, not generated by the painter.
			if !strings.Contains(text, "██╔════╝██╔══██╗") || !strings.Contains(text, "Choose a project workspace") {
				t.Fatalf("navigation-only startup lost its branded chooser:\n%s", text)
			}
			if strings.Contains(text, "Welcome to Crude") || strings.Contains(text, "Let's go!") {
				t.Fatal("chooser must not replay the introduction")
			}
			click(t, m, openID)
			if m.root.mode != picking {
				t.Fatal("branded chooser's Open Workspace did not open the folder picker")
			}
			send(t, m, key(tea.KeyEsc))
			if !strings.Contains(paintText(m), "██╔════╝██╔══██╗") {
				t.Fatal("returning from the folder picker lost the banner")
			}
		})
	}
}

// startupRowText returns one painted buffer row as text.
func startupRowText(m *Model, y int) string {
	buf := m.surf.Buffer()
	if y < 0 || y >= buf.Height() {
		return ""
	}
	var b strings.Builder
	for _, c := range buf.Row(y) {
		if c.Width == 0 {
			continue
		}
		if c.Char == 0 {
			b.WriteRune(' ')
			continue
		}
		b.WriteRune(c.Char)
	}
	return b.String()
}

// bannerBlock captures the wordmark cells from the page's own content column so
// two pages can be compared cell for cell.
func bannerBlock(t *testing.T, m *Model) [][]cell.Cell {
	t.Helper()
	c := m.root.content
	if c.Empty() {
		t.Fatal("startup content has no geometry")
	}
	buf := m.surf.Buffer()
	block := make([][]cell.Cell, ui.BannerHeight)
	for row := range block {
		line := make([]cell.Cell, c.W)
		for x := 0; x < c.W; x++ {
			line[x] = buf.Get(c.X+x, c.Y+row)
		}
		block[row] = line
	}
	return block
}

func renderStartup(m *Model) { _ = m.View() }

// bannerLineText returns one painted wordmark row of the current page.
func bannerLineText(m *Model, row int) string {
	return strings.TrimRight(startupRowText(m, m.root.content.Y+row), " ")
}

// assertWordmark proves the page opens with the shared wordmark exactly once.
func assertWordmark(t *testing.T, m *Model, page string) [][]cell.Cell {
	t.Helper()
	block := bannerBlock(t, m)
	for i, want := range ui.BannerText() {
		if got := bannerLineText(m, i); !strings.Contains(got, strings.TrimRight(want, " ")) {
			t.Fatalf("%s row %d = %q, want wordmark %q", page, i, got, want)
		}
	}
	for y := 0; y < m.surf.Buffer().Height(); y++ {
		if y >= m.root.content.Y && y < m.root.content.Y+ui.BannerHeight {
			continue
		}
		if strings.Contains(startupRowText(m, y), "██████╗") {
			t.Fatalf("%s paints a second wordmark at row %d", page, y)
		}
	}
	return block
}

// TestEveryPreWorkspacePagePaintsTheSameBanner is the consistency contract: the
// introduction and the project chooser are one identity, not two designs.
func TestEveryPreWorkspacePagePaintsTheSameBanner(t *testing.T) {
	for _, preset := range []string{"dark", "light"} {
		t.Run(preset, func(t *testing.T) {
			m := fixture(t, &fakeStartup{}, true)
			m.host.SetTheme(ui.ThemeFromPreset(preset))
			send(t, m, tea.WindowSizeMsg{Width: 100, Height: 30})

			renderStartup(m)
			intro := assertWordmark(t, m, "introduction")

			send(t, m, key(tea.KeyEnter))
			send(t, m, key(tea.KeyEsc))
			if m.root.mode != selection {
				t.Fatalf("Esc left the project picker in phase %v", m.root.mode)
			}

			renderStartup(m)
			chooser := assertWordmark(t, m, "project chooser")
			for row := range intro {
				for x := range intro[row] {
					if intro[row][x] != chooser[row][x] {
						t.Fatalf("row %d cell %d differs between pages:\n intro=%+v\nchooser=%+v", row, x, intro[row][x], chooser[row][x])
					}
				}
			}
		})
	}
}

// TestChooserBannerLeavesItsContentReadable keeps the identity from eating the
// page: nothing above the banner, no body text inside it, and the list still
// has its own rows at the narrow desktop size.
func TestChooserBannerLeavesItsContentReadable(t *testing.T) {
	m := fixture(t, &fakeStartup{}, true)
	send(t, m, tea.WindowSizeMsg{Width: 80, Height: 24})
	send(t, m, key(tea.KeyEnter))
	send(t, m, key(tea.KeyEsc))

	renderStartup(m)
	content, bannerTop := m.root.content, m.root.content.Y
	bannerBottom := bannerTop + ui.BannerHeight - 1
	for y := 0; y < bannerTop+ui.BannerHeight; y++ {
		text := strings.TrimSpace(startupRowText(m, y))
		if y >= bannerTop && y <= bannerBottom {
			if strings.Contains(text, "Choose a project workspace") || strings.Contains(text, "Open Workspace") || strings.Contains(text, "Previous workspaces") {
				t.Fatalf("body text %q shares a row with the banner at row %d", text, y)
			}
			continue
		}
		if text != "" {
			t.Fatalf("row %d above the banner is not empty: %q", y, text)
		}
	}
	for _, want := range []string{"Choose a project workspace", "Previous workspaces", "Open Workspace", "Quit", "/home/demo"} {
		found := false
		for y := bannerBottom + 1; y < m.surf.Buffer().Height(); y++ {
			if strings.Contains(startupRowText(m, y), want) {
				found = true
				break
			}
		}
		if !found {
			t.Fatalf("%q is not painted below the banner", want)
		}
	}
	list, ok := m.host.ScreenRect(previousID)
	if !ok || list.H < 1 {
		t.Fatalf("previous-workspace list has no rows below the banner: %+v mounted=%v", list, ok)
	}
	if list.Y <= content.Y+ui.BannerHeight {
		t.Fatalf("list overlaps the banner: %+v", list)
	}
	if quit, ok := m.host.ScreenRect(quitID); !ok || quit.Y <= list.Y+list.H {
		t.Fatalf("Quit does not follow the list: %+v", quit)
	}
}

// TestChooserKeepsNarrowWidthsIntact proves the wordmark truncates instead of
// widening the page into the terminal edges.
func TestChooserKeepsNarrowWidthsIntact(t *testing.T) {
	for _, width := range []int{40, 60} {
		m := fixture(t, &fakeStartup{}, false)
		send(t, m, tea.WindowSizeMsg{Width: width, Height: 24})
		renderStartup(m)
		for y := 0; y < m.surf.Buffer().Height(); y++ {
			row := startupRowText(m, y)
			if len([]rune(row)) > width {
				t.Fatalf("width %d: row %d exceeds the terminal: %q", width, y, row)
			}
		}
		if !strings.ContainsRune(bannerLineText(m, 0), '█') {
			t.Fatalf("width %d: banner is not painted", width)
		}
	}
}

// TestChooserBannerSurvivesRecoveryIssues keeps the identity stable when the
// page also has to show operational issues.
func TestChooserBannerSurvivesRecoveryIssues(t *testing.T) {
	m := fixture(t, &fakeStartup{}, false)
	send(t, m, tea.WindowSizeMsg{Width: 100, Height: 30})
	m.addIssues(types.OperationIssue{Title: "Configuration needs repair", Detail: "accounts need repair"})
	renderStartup(m)
	if !strings.ContainsRune(bannerLineText(m, 0), '█') {
		t.Fatal("issues removed the banner")
	}
	if issues, ok := m.host.ScreenRect(issuesID); ok && issues.Y <= m.root.content.Y+ui.BannerHeight {
		t.Fatalf("issue block overlaps the banner: %+v", issues)
	}
}
